import { createHmac, timingSafeEqual } from 'crypto'
import type { NextRequest, NextResponse } from 'next/server'
import { getSessionSecret } from '@/lib/session'

// Rider auth cookie. Separate from yff_consumer so a consumer logged into
// the storefront can't accidentally act as a delivery boy (and vice versa).
// Both share SESSION_SECRET — the cookie name is included in the HMAC so a
// stolen consumer token can't be replayed against a rider endpoint.
const COOKIE_NAME = 'yff_rider'
const TOKEN_TTL_MS = 30 * 24 * 60 * 60 * 1000

function b64url(buf: Buffer): string {
  return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

function sign(payload: string): string {
  const secret = getSessionSecret()
  return b64url(createHmac('sha256', secret).update(`rider:${payload}`).digest())
}

export function createRiderSessionToken(riderId: string): string {
  const issuedAt = Date.now()
  const payload = `${riderId}.${issuedAt}`
  return `${payload}.${sign(payload)}`
}

export type RiderSessionPayload = { riderId: string; issuedAt: number }

export function verifyRiderSessionToken(token: string | undefined | null): RiderSessionPayload | null {
  if (!token) return null
  const parts = token.split('.')
  if (parts.length !== 3) return null
  const [riderId, issuedAtStr, sig] = parts
  const issuedAt = Number(issuedAtStr)
  if (!riderId || !Number.isFinite(issuedAt)) return null
  if (Date.now() - issuedAt > TOKEN_TTL_MS) return null

  let expected: string
  try {
    expected = sign(`${riderId}.${issuedAtStr}`)
  } catch {
    return null
  }
  const a = Buffer.from(sig)
  const b = Buffer.from(expected)
  if (a.length !== b.length) return null
  if (!timingSafeEqual(a, b)) return null
  return { riderId, issuedAt }
}

export function getRiderSessionFromRequest(req: NextRequest): RiderSessionPayload | null {
  const token = req.cookies.get(COOKIE_NAME)?.value
  return verifyRiderSessionToken(token)
}

export function setRiderSessionCookie(res: NextResponse, riderId: string): void {
  const token = createRiderSessionToken(riderId)
  res.cookies.set(COOKIE_NAME, token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: Math.floor(TOKEN_TTL_MS / 1000),
  })
}

export function clearRiderSessionCookie(res: NextResponse): void {
  res.cookies.set(COOKIE_NAME, '', {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: 0,
  })
}

export const RIDER_SESSION_COOKIE_NAME = COOKIE_NAME

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'

export default function AdminLoginPage() {
  const router = useRouter()
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [submitting, setSubmitting] = useState(false)

  const submit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (submitting) return
    setError('')
    setSubmitting(true)
    const r = await fetch('/api/admin/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify({ password }),
    }).catch(() => null)
    setSubmitting(false)
    if (!r) { setError('Network error. / నెట్‌వర్క్ లోపం'); return }
    const json = await r.json().catch(() => ({}))
    if (!r.ok || !json?.ok) { setError(json?.error ?? 'Login failed. / లాగిన్ విఫలమైంది'); return }
    router.replace('/admin')
  }

  return (
    <main className="min-h-screen bg-gray-50 flex flex-col">
      <div className="bg-gray-900 px-4 pt-10 pb-14">
        <h1 className="text-white text-2xl font-extrabold">Owner panel</h1>
        <p className="text-gray-300 text-sm">యజమాని ప్యానెల్</p>
        <p className="text-gray-400 text-xs mt-1">Internal · password protected / అంతర్గత · పాస్‌వర్డ్ రక్షణ</p>
      </div>
      <form
        onSubmit={submit}
        className="bg-white rounded-2xl shadow-md mx-4 -mt-6 p-5 space-y-4 max-w-md w-full mx-auto"
      >
        <div>
          <label className="text-xs font-bold text-gray-700 uppercase tracking-wide block mb-1">
            Admin password / అడ్మిన్ పాస్‌వర్డ్
          </label>
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="w-full border border-gray-200 rounded-xl px-4 py-3 text-base focus:border-green-500 focus:outline-none"
            required
            autoFocus
          />
        </div>
        {error && (
          <p className="text-xs text-red-700 bg-red-50 border border-red-200 rounded-xl px-3 py-2 font-semibold">
            {error}
          </p>
        )}
        <button
          type="submit"
          disabled={submitting}
          className="w-full bg-gray-900 text-white font-bold py-4 rounded-xl text-base active:bg-gray-800 disabled:opacity-50"
        >
          {submitting ? 'Checking... / తనిఖీ చేస్తోంది...' : 'Log in / లాగిన్'}
        </button>
      </form>
    </main>
  )
}

import { createHmac, timingSafeEqual } from 'crypto'
import type { NextRequest, NextResponse } from 'next/server'

// HMAC-signed session token (server-only). Stored in an HTTP-only cookie so
// XSS cannot exfiltrate it. Format: <consumerId>.<issuedAtMs>.<hmacHexBase64url>
//
// We never put consumer name or phone in the token — those live in the DB.
// localStorage holds the public profile copy used purely for UI display, and
// the server re-derives identity from the cookie on every request.

const COOKIE_NAME = 'yff_consumer'
const TOKEN_TTL_MS = 30 * 24 * 60 * 60 * 1000 // 30 days

export function getSessionSecret(): string {
  const secret = process.env.SESSION_SECRET
  if (!secret || secret.length < 32) {
    throw new Error(
      'SESSION_SECRET env var is missing or too short. Set a 32+ char random string in your environment (e.g. `openssl rand -hex 32`).',
    )
  }
  return secret
}

function b64url(buf: Buffer): string {
  return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

function sign(payload: string): string {
  const secret = getSessionSecret()
  return b64url(createHmac('sha256', secret).update(payload).digest())
}

export function createSessionToken(consumerId: string): string {
  const issuedAt = Date.now()
  const payload = `${consumerId}.${issuedAt}`
  const sig = sign(payload)
  return `${payload}.${sig}`
}

export type SessionPayload = { consumerId: string; issuedAt: number }

export function verifySessionToken(token: string | undefined | null): SessionPayload | null {
  if (!token) return null
  const parts = token.split('.')
  if (parts.length !== 3) return null
  const [consumerId, issuedAtStr, sig] = parts
  const issuedAt = Number(issuedAtStr)
  if (!consumerId || !Number.isFinite(issuedAt)) return null
  if (Date.now() - issuedAt > TOKEN_TTL_MS) return null

  let expected: string
  try {
    expected = sign(`${consumerId}.${issuedAtStr}`)
  } catch {
    return null
  }
  const a = Buffer.from(sig)
  const b = Buffer.from(expected)
  if (a.length !== b.length) return null
  if (!timingSafeEqual(a, b)) return null
  return { consumerId, issuedAt }
}

export function getConsumerSessionFromRequest(req: NextRequest): SessionPayload | null {
  const token = req.cookies.get(COOKIE_NAME)?.value
  return verifySessionToken(token)
}

export function setSessionCookie(res: NextResponse, consumerId: string): void {
  const token = createSessionToken(consumerId)
  res.cookies.set(COOKIE_NAME, token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: Math.floor(TOKEN_TTL_MS / 1000),
  })
}

export function clearSessionCookie(res: NextResponse): void {
  res.cookies.set(COOKIE_NAME, '', {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: 0,
  })
}

export const CONSUMER_SESSION_COOKIE_NAME = COOKIE_NAME

